CREATE FUNCTION is_prime_digit_sum(n INT)
RETURNS BOOLEAN
BEGIN
  DECLARE sum INT DEFAULT 0;
  DECLARE i INT DEFAULT 1;
  WHILE n > 0 DO
    SET sum = sum + MOD(n, 10);
    SET n = FLOOR(n / 10);
  END WHILE;
  IF sum < 2 THEN
    RETURN FALSE;
  END IF;
  WHILE i * i <= sum DO
